CREATE TABLE IF NOT EXISTS `sites` (`id` INT AUTO_INCREMENT NOT NULL PRIMARY KEY, `name` TEXT NOT NULL, `url` TEXT NOT NULL, `external_checkin_url` TEXT, `platform` TEXT NOT NULL, `proxy_url` TEXT, `use_system_proxy` BOOLEAN DEFAULT false, `custom_headers` JSON, `compatibility_policy` TEXT, `status` VARCHAR(191) NOT NULL DEFAULT 'active', `is_pinned` BOOLEAN DEFAULT false, `sort_order` INT DEFAULT 0, `global_weight` DOUBLE DEFAULT 1, `api_key` TEXT, `post_refresh_probe_enabled` BOOLEAN DEFAULT false, `post_refresh_probe_model` VARCHAR(191) DEFAULT '', `post_refresh_probe_scope` VARCHAR(191) DEFAULT 'single', `post_refresh_probe_latency_threshold_ms` INT DEFAULT 0, `created_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `updated_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')));
CREATE TABLE IF NOT EXISTS `accounts` (`id` INT AUTO_INCREMENT NOT NULL PRIMARY KEY, `site_id` INT NOT NULL, `username` TEXT, `access_token` TEXT NOT NULL, `api_token` TEXT, `balance` DOUBLE DEFAULT 0, `balance_used` DOUBLE DEFAULT 0, `quota` DOUBLE DEFAULT 0, `unit_cost` DOUBLE, `value_score` DOUBLE DEFAULT 0, `status` VARCHAR(191) DEFAULT 'active', `is_pinned` BOOLEAN DEFAULT false, `sort_order` INT DEFAULT 0, `checkin_enabled` BOOLEAN DEFAULT true, `last_checkin_at` VARCHAR(191), `last_balance_refresh` VARCHAR(191), `oauth_provider` TEXT, `oauth_account_key` TEXT, `oauth_project_id` TEXT, `extra_config` JSON, `created_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `updated_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), FOREIGN KEY (`site_id`) REFERENCES `sites`(`id`) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS `account_tokens` (`id` INT AUTO_INCREMENT NOT NULL PRIMARY KEY, `account_id` INT NOT NULL, `name` TEXT NOT NULL, `token` TEXT NOT NULL, `token_group` TEXT, `compatibility_policy` TEXT, `value_status` VARCHAR(191) NOT NULL DEFAULT 'ready', `source` VARCHAR(191) DEFAULT 'manual', `enabled` BOOLEAN DEFAULT true, `is_default` BOOLEAN DEFAULT false, `created_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `updated_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), FOREIGN KEY (`account_id`) REFERENCES `accounts`(`id`) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS `admin_snapshots` (`id` INT AUTO_INCREMENT NOT NULL PRIMARY KEY, `namespace` TEXT NOT NULL, `snapshot_key` TEXT NOT NULL, `payload` TEXT NOT NULL, `generated_at` VARCHAR(191) NOT NULL, `expires_at` VARCHAR(191) NOT NULL, `stale_until` VARCHAR(191) NOT NULL, `created_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `updated_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')));
CREATE TABLE IF NOT EXISTS `analytics_projection_checkpoints` (`projector_key` VARCHAR(191) NOT NULL PRIMARY KEY, `time_zone` VARCHAR(191) NOT NULL DEFAULT 'Local', `last_proxy_log_id` INT NOT NULL DEFAULT 0, `last_proxy_request_completed_at` VARCHAR(191), `last_proxy_request_id` TEXT, `watermark_created_at` VARCHAR(191), `lease_owner` TEXT, `lease_token` TEXT, `lease_expires_at` VARCHAR(191), `recompute_from_id` INT, `recompute_requested_at` VARCHAR(191), `recompute_reason` TEXT, `recompute_started_at` VARCHAR(191), `recompute_completed_at` VARCHAR(191), `last_projected_at` VARCHAR(191), `last_successful_at` VARCHAR(191), `last_error` TEXT, `created_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `updated_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')));
CREATE TABLE IF NOT EXISTS `model_catalog_sources` (`id` INT AUTO_INCREMENT NOT NULL PRIMARY KEY, `site_id` INT NOT NULL, `source_key` TEXT NOT NULL, `label` TEXT NOT NULL, `discovery_method` VARCHAR(191) NOT NULL DEFAULT 'GET', `discovery_url` TEXT, `parser` VARCHAR(191) NOT NULL DEFAULT 'openai_models', `credential_scope` VARCHAR(191) NOT NULL DEFAULT 'credential', `refresh_policy_json` JSON, `enabled` BOOLEAN NOT NULL DEFAULT true, `metadata_json` JSON, `last_refresh_at` VARCHAR(191), `last_model_count` INT DEFAULT 0, `last_error` TEXT, `created_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `updated_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), FOREIGN KEY (`site_id`) REFERENCES `sites`(`id`) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS `api_endpoint_profiles` (`id` INT AUTO_INCREMENT NOT NULL PRIMARY KEY, `site_id` INT NOT NULL, `profile_key` TEXT NOT NULL, `api_type` TEXT NOT NULL, `label` TEXT NOT NULL, `request_method` VARCHAR(191) NOT NULL DEFAULT 'POST', `request_url` TEXT, `default_headers_json` JSON, `model_catalog_source_id` INT, `auth_mode` VARCHAR(191) NOT NULL DEFAULT 'bearer', `enabled` BOOLEAN NOT NULL DEFAULT true, `priority` INT DEFAULT 0, `capability_defaults_json` JSON, `compatibility_policy_ref` TEXT, `metadata_json` JSON, `created_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `updated_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), FOREIGN KEY (`model_catalog_source_id`) REFERENCES `model_catalog_sources`(`id`) ON DELETE SET NULL, FOREIGN KEY (`site_id`) REFERENCES `sites`(`id`) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS `billing_cost_aggregates` (`id` INT AUTO_INCREMENT NOT NULL PRIMARY KEY, `observation_grain` TEXT NOT NULL, `bucket_kind` TEXT NOT NULL, `bucket_start` TEXT NOT NULL, `subject_kind` TEXT NOT NULL, `subject_key` TEXT NOT NULL, `dimension_key` TEXT NOT NULL, `site_id` INT, `account_id` INT, `model` TEXT, `route_entrypoint_id` TEXT, `runtime_endpoint_id` TEXT, `execution_attempt_id` TEXT, `downstream_api_key_id` INT, `quote_unit` TEXT NOT NULL, `currency_key` VARCHAR(191) NOT NULL DEFAULT '', `quote_source` TEXT NOT NULL, `quote_source_id_key` VARCHAR(191) NOT NULL DEFAULT '', `estimate_level_key` VARCHAR(191) NOT NULL DEFAULT '', `plan_fingerprint_key` VARCHAR(191) NOT NULL DEFAULT '', `total_amount` DOUBLE, `known_observation_count` INT NOT NULL DEFAULT 0, `unknown_observation_count` INT NOT NULL DEFAULT 0, `created_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `updated_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), FOREIGN KEY (`account_id`) REFERENCES `accounts`(`id`) ON DELETE CASCADE, FOREIGN KEY (`site_id`) REFERENCES `sites`(`id`) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS `checkin_logs` (`id` INT AUTO_INCREMENT NOT NULL PRIMARY KEY, `account_id` INT NOT NULL, `status` TEXT NOT NULL, `message` TEXT, `reward` TEXT, `created_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), FOREIGN KEY (`account_id`) REFERENCES `accounts`(`id`) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS `route_graph_versions` (`id` INT AUTO_INCREMENT NOT NULL PRIMARY KEY, `version` INT NOT NULL, `source_graph_json` JSON NOT NULL, `status` VARCHAR(191) NOT NULL DEFAULT 'archived', `created_by` VARCHAR(191) DEFAULT 'system', `created_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `activated_at` VARCHAR(191));
CREATE TABLE IF NOT EXISTS `compiled_runtime_artifacts` (`id` VARCHAR(191) NOT NULL PRIMARY KEY, `artifact_json` JSON NOT NULL, `bundle_hash` TEXT NOT NULL, `source_graph_version_id` INT, `source_graph_hash` TEXT, `created_at` VARCHAR(191) NOT NULL DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), FOREIGN KEY (`source_graph_version_id`) REFERENCES `route_graph_versions`(`id`) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS `compiled_runtime_active_artifact` (`id` INT AUTO_INCREMENT NOT NULL PRIMARY KEY, `artifact_id` VARCHAR(191) NOT NULL, `updated_at` VARCHAR(191) NOT NULL DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), FOREIGN KEY (`artifact_id`) REFERENCES `compiled_runtime_artifacts`(`id`) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS `credential_endpoint_bindings` (`id` INT AUTO_INCREMENT NOT NULL PRIMARY KEY, `site_id` INT NOT NULL, `account_id` INT, `token_id` INT, `credential_key` TEXT NOT NULL, `credential_kind` TEXT NOT NULL, `api_endpoint_profile_id` INT NOT NULL, `enabled` BOOLEAN NOT NULL DEFAULT true, `support` VARCHAR(191) NOT NULL DEFAULT 'supported', `source` VARCHAR(191) NOT NULL DEFAULT 'manual', `priority` INT DEFAULT 0, `capability_override_json` JSON, `compatibility_policy_ref` TEXT, `pricing_policy_ref` TEXT, `measured_pricing_ref` TEXT, `metadata_json` JSON, `created_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `updated_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), FOREIGN KEY (`account_id`) REFERENCES `accounts`(`id`) ON DELETE CASCADE, FOREIGN KEY (`api_endpoint_profile_id`) REFERENCES `api_endpoint_profiles`(`id`) ON DELETE CASCADE, FOREIGN KEY (`site_id`) REFERENCES `sites`(`id`) ON DELETE CASCADE, FOREIGN KEY (`token_id`) REFERENCES `account_tokens`(`id`) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS `downstream_api_keys` (`id` INT AUTO_INCREMENT NOT NULL PRIMARY KEY, `name` TEXT NOT NULL, `key` TEXT NOT NULL, `description` TEXT, `group_name` TEXT, `tags` TEXT, `enabled` BOOLEAN DEFAULT true, `expires_at` VARCHAR(191), `max_cost` DOUBLE, `used_cost` DOUBLE DEFAULT 0, `max_requests` INT, `used_requests` INT DEFAULT 0, `supported_models` JSON, `allowed_plan_ids` TEXT, `site_weight_multipliers` JSON, `excluded_site_ids` JSON, `excluded_credential_refs` JSON, `last_used_at` VARCHAR(191), `created_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `updated_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')));
CREATE TABLE IF NOT EXISTS `endpoint_model_observations` (`id` INT AUTO_INCREMENT NOT NULL PRIMARY KEY, `site_id` INT NOT NULL, `credential_key` TEXT NOT NULL, `api_endpoint_profile_id` INT NOT NULL, `model_name` TEXT NOT NULL, `status` TEXT NOT NULL, `failure_class` TEXT, `source` VARCHAR(191) NOT NULL DEFAULT 'runtime', `observed_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `expires_at` VARCHAR(191), `metadata_json` JSON, FOREIGN KEY (`api_endpoint_profile_id`) REFERENCES `api_endpoint_profiles`(`id`) ON DELETE CASCADE, FOREIGN KEY (`site_id`) REFERENCES `sites`(`id`) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS `events` (`id` INT AUTO_INCREMENT NOT NULL PRIMARY KEY, `type` TEXT NOT NULL, `title` TEXT NOT NULL, `summary` TEXT, `description` TEXT, `message` TEXT, `level` VARCHAR(191) NOT NULL DEFAULT 'info', `severity` VARCHAR(191) NOT NULL DEFAULT 'info', `scope` VARCHAR(191) NOT NULL DEFAULT 'activity', `category` TEXT, `state` VARCHAR(191) NOT NULL DEFAULT 'open', `read` BOOLEAN DEFAULT false, `read_at` VARCHAR(191), `acknowledged_at` VARCHAR(191), `snoozed_until` VARCHAR(191), `resolved_at` VARCHAR(191), `subject_type` TEXT, `subject_id` TEXT, `subject_label` TEXT, `details_json` JSON, `actions_json` JSON, `dedupe_key` TEXT, `occurrence_count` INT NOT NULL DEFAULT 1, `first_seen_at` VARCHAR(191), `last_seen_at` VARCHAR(191), `source` TEXT, `related_id` INT, `related_type` TEXT, `created_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `updated_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')));
CREATE TABLE IF NOT EXISTS `fx_rate_snapshots` (`id` INT AUTO_INCREMENT NOT NULL PRIMARY KEY, `from_currency` TEXT NOT NULL, `to_currency` TEXT NOT NULL, `rate` DOUBLE NOT NULL, `source` VARCHAR(191) NOT NULL DEFAULT 'manual', `captured_at` VARCHAR(191) NOT NULL DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `notes` TEXT, `created_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `updated_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')));
CREATE TABLE IF NOT EXISTS `model_availability` (`id` INT AUTO_INCREMENT NOT NULL PRIMARY KEY, `account_id` INT NOT NULL, `model_name` TEXT NOT NULL, `available` BOOLEAN, `is_manual` BOOLEAN DEFAULT false, `latency_ms` INT, `checked_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), FOREIGN KEY (`account_id`) REFERENCES `accounts`(`id`) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS `model_day_usage` (`id` INT AUTO_INCREMENT NOT NULL PRIMARY KEY, `local_day` TEXT NOT NULL, `site_id` INT NOT NULL, `account_id` INT NOT NULL, `model` TEXT NOT NULL, `total_calls` INT NOT NULL DEFAULT 0, `success_calls` INT NOT NULL DEFAULT 0, `failed_calls` INT NOT NULL DEFAULT 0, `total_tokens` INT NOT NULL DEFAULT 0, `total_latency_ms` INT NOT NULL DEFAULT 0, `latency_count` INT NOT NULL DEFAULT 0, `created_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `updated_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), FOREIGN KEY (`account_id`) REFERENCES `accounts`(`id`) ON DELETE CASCADE, FOREIGN KEY (`site_id`) REFERENCES `sites`(`id`) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS `oauth_route_units` (`id` INT AUTO_INCREMENT NOT NULL PRIMARY KEY, `site_id` INT NOT NULL, `provider` TEXT NOT NULL, `name` TEXT NOT NULL, `strategy` VARCHAR(191) NOT NULL DEFAULT 'round_robin', `enabled` BOOLEAN DEFAULT true, `created_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `updated_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), FOREIGN KEY (`site_id`) REFERENCES `sites`(`id`) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS `oauth_route_unit_members` (`id` INT AUTO_INCREMENT NOT NULL PRIMARY KEY, `unit_id` INT NOT NULL, `account_id` INT NOT NULL, `sort_order` INT DEFAULT 0, `success_count` INT DEFAULT 0, `fail_count` INT DEFAULT 0, `total_latency_ms` INT DEFAULT 0, `total_cost` DOUBLE DEFAULT 0, `last_used_at` VARCHAR(191), `last_selected_at` VARCHAR(191), `last_fail_at` VARCHAR(191), `consecutive_fail_count` INT NOT NULL DEFAULT 0, `cooldown_level` INT NOT NULL DEFAULT 0, `cooldown_until` VARCHAR(191), `created_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `updated_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), FOREIGN KEY (`account_id`) REFERENCES `accounts`(`id`) ON DELETE CASCADE, FOREIGN KEY (`unit_id`) REFERENCES `oauth_route_units`(`id`) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS `provider_pricing_catalog_caches` (`id` INT AUTO_INCREMENT NOT NULL PRIMARY KEY, `scope_key` TEXT NOT NULL, `site_id` INT NOT NULL, `account_id` INT, `platform` TEXT NOT NULL, `credential_kind` TEXT, `catalog_json` JSON, `model_count` INT NOT NULL DEFAULT 0, `group_count` INT NOT NULL DEFAULT 0, `catalog_fingerprint` TEXT, `last_status` VARCHAR(191) NOT NULL DEFAULT 'success', `last_error` TEXT, `diagnostics_json` JSON, `fetched_at` VARCHAR(191) NOT NULL DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `expires_at` VARCHAR(191) NOT NULL, `created_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `updated_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), FOREIGN KEY (`account_id`) REFERENCES `accounts`(`id`) ON DELETE CASCADE, FOREIGN KEY (`site_id`) REFERENCES `sites`(`id`) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS `proxy_debug_traces` (`id` INT AUTO_INCREMENT NOT NULL PRIMARY KEY, `downstream_path` TEXT NOT NULL, `client_kind` TEXT, `session_id` TEXT, `trace_hint` TEXT, `requested_model` TEXT, `downstream_api_key_id` INT, `request_headers_json` JSON, `request_body_json` JSON, `sticky_session_key` TEXT, `sticky_hit_execution_attempt_id` TEXT, `selected_execution_attempt_id` TEXT, `route_entrypoint_id` TEXT, `runtime_endpoint_id` TEXT, `selected_account_id` INT, `selected_site_id` INT, `selected_site_platform` TEXT, `runtime_trace_json` JSON, `final_status` TEXT, `final_http_status` INT, `final_upstream_path` TEXT, `final_response_headers_json` JSON, `final_response_body_json` JSON, `created_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `updated_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')));
CREATE TABLE IF NOT EXISTS `proxy_debug_attempts` (`id` INT AUTO_INCREMENT NOT NULL PRIMARY KEY, `trace_id` INT NOT NULL, `attempt_index` INT NOT NULL, `endpoint` TEXT NOT NULL, `request_path` TEXT NOT NULL, `target_url` TEXT NOT NULL, `runtime_executor` TEXT, `request_headers_json` JSON, `request_body_json` JSON, `response_status` INT, `response_headers_json` JSON, `response_body_json` JSON, `raw_error_text` TEXT, `recover_applied` BOOLEAN DEFAULT false, `downgrade_decision` BOOLEAN DEFAULT false, `downgrade_reason` TEXT, `fallback_scope` TEXT, `failure_class` TEXT, `memory_write_json` JSON, `created_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), FOREIGN KEY (`trace_id`) REFERENCES `proxy_debug_traces`(`id`) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS `proxy_files` (`id` INT AUTO_INCREMENT NOT NULL PRIMARY KEY, `public_id` TEXT NOT NULL, `owner_type` TEXT NOT NULL, `owner_id` TEXT NOT NULL, `filename` TEXT NOT NULL, `mime_type` TEXT NOT NULL, `purpose` TEXT, `byte_size` INT NOT NULL, `sha256` TEXT NOT NULL, `content_base64` TEXT NOT NULL, `created_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `updated_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `deleted_at` VARCHAR(191));
CREATE TABLE IF NOT EXISTS `proxy_requests` (`id` VARCHAR(191) NOT NULL PRIMARY KEY, `downstream_path` TEXT NOT NULL, `requested_model` TEXT, `actual_model` TEXT, `final_site_id` INT, `final_account_id` INT, `downstream_api_key_id` INT, `route_entrypoint_id` TEXT, `runtime_endpoint_id` TEXT, `final_execution_attempt_id` TEXT, `runtime_bundle_hash` TEXT, `status` VARCHAR(191) NOT NULL DEFAULT 'started', `http_status` INT, `is_stream` BOOLEAN, `latency_ms` INT, `first_token_latency_ms` INT, `prompt_tokens` INT, `completion_tokens` INT, `total_tokens` INT, `estimated_cost` DOUBLE, `billing_details` JSON, `decision_snapshot` JSON, `error_message` TEXT, `started_at` VARCHAR(191) NOT NULL DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `completed_at` VARCHAR(191), FOREIGN KEY (`final_account_id`) REFERENCES `accounts`(`id`) ON DELETE SET NULL, FOREIGN KEY (`final_site_id`) REFERENCES `sites`(`id`) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS `proxy_logs` (`id` INT AUTO_INCREMENT NOT NULL PRIMARY KEY, `request_id` VARCHAR(191), `execution_attempt_id` TEXT, `account_id` INT, `downstream_api_key_id` INT, `model_requested` TEXT, `model_actual` TEXT, `route_entrypoint_id` TEXT, `runtime_endpoint_id` TEXT, `runtime_artifact_id` TEXT, `execution_target_id` INT, `status` TEXT, `http_status` INT, `is_stream` BOOLEAN, `first_byte_latency_ms` INT, `first_token_latency_ms` INT, `latency_ms` INT, `prompt_tokens` INT, `completion_tokens` INT, `total_tokens` INT, `estimated_cost` DOUBLE, `billing_details` JSON, `client_family` TEXT, `client_app_id` TEXT, `client_app_name` TEXT, `client_confidence` TEXT, `error_message` TEXT, `retry_count` INT DEFAULT 0, `created_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), FOREIGN KEY (`request_id`) REFERENCES `proxy_requests`(`id`) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS `proxy_video_tasks` (`id` INT AUTO_INCREMENT NOT NULL PRIMARY KEY, `public_id` TEXT NOT NULL, `upstream_video_id` TEXT NOT NULL, `site_url` TEXT NOT NULL, `token_value` TEXT NOT NULL, `requested_model` TEXT, `actual_model` TEXT, `execution_target_id` INT, `account_id` INT, `status_snapshot` JSON, `upstream_response_meta` JSON, `last_upstream_status` INT, `last_polled_at` VARCHAR(191), `created_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `updated_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')));
CREATE TABLE IF NOT EXISTS `route_graph_active_version` (`id` INT AUTO_INCREMENT NOT NULL PRIMARY KEY, `version_id` INT NOT NULL, `updated_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), FOREIGN KEY (`version_id`) REFERENCES `route_graph_versions`(`id`) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS `route_graph_drafts` (`id` INT AUTO_INCREMENT NOT NULL PRIMARY KEY, `base_version` INT, `revision` INT NOT NULL DEFAULT 0, `working_graph_json` JSON NOT NULL, `status` VARCHAR(191) NOT NULL DEFAULT 'active', `diagnostics_json` JSON, `updated_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), FOREIGN KEY (`base_version`) REFERENCES `route_graph_versions`(`id`) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS `route_graph_workspace_operation_batches` (`id` INT AUTO_INCREMENT NOT NULL PRIMARY KEY, `draft_id` INT NOT NULL, `source_revision` INT NOT NULL, `result_revision` INT NOT NULL, `forward_operations_json` JSON NOT NULL, `inverse_operations_json` JSON NOT NULL, `created_at` VARCHAR(191) NOT NULL DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), FOREIGN KEY (`draft_id`) REFERENCES `route_graph_drafts`(`id`) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS `route_runtime_day_usage` (`id` INT AUTO_INCREMENT NOT NULL PRIMARY KEY, `local_day` TEXT NOT NULL, `runtime_identity_key` TEXT NOT NULL, `route_entrypoint_id` TEXT, `runtime_endpoint_id` TEXT, `execution_target_id` INT, `execution_attempt_id` TEXT, `site_id` INT, `account_id` INT, `model` TEXT NOT NULL, `total_calls` INT NOT NULL DEFAULT 0, `success_calls` INT NOT NULL DEFAULT 0, `failed_calls` INT NOT NULL DEFAULT 0, `total_tokens` INT NOT NULL DEFAULT 0, `total_latency_ms` INT NOT NULL DEFAULT 0, `latency_count` INT NOT NULL DEFAULT 0, `created_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `updated_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), FOREIGN KEY (`account_id`) REFERENCES `accounts`(`id`) ON DELETE CASCADE, FOREIGN KEY (`site_id`) REFERENCES `sites`(`id`) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS `runtime_execution_targets` (`id` INT AUTO_INCREMENT NOT NULL PRIMARY KEY, `source_ref` TEXT NOT NULL, `execution_key` TEXT NOT NULL, `site_id` INT NOT NULL, `account_id` INT, `token_id` INT, `oauth_route_unit_id` INT, `credential_binding_id` INT, `endpoint_profile_id` INT, `upstream_model_name` TEXT NOT NULL, `normalized_model_name` TEXT NOT NULL, `enabled` BOOLEAN NOT NULL DEFAULT true, `discovered` BOOLEAN NOT NULL DEFAULT true, `source` VARCHAR(191) NOT NULL DEFAULT 'availability_rebuild', `metadata_json` JSON, `created_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `updated_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), FOREIGN KEY (`account_id`) REFERENCES `accounts`(`id`) ON DELETE CASCADE, FOREIGN KEY (`credential_binding_id`) REFERENCES `credential_endpoint_bindings`(`id`) ON DELETE SET NULL, FOREIGN KEY (`endpoint_profile_id`) REFERENCES `api_endpoint_profiles`(`id`) ON DELETE SET NULL, FOREIGN KEY (`oauth_route_unit_id`) REFERENCES `oauth_route_units`(`id`) ON DELETE SET NULL, FOREIGN KEY (`site_id`) REFERENCES `sites`(`id`) ON DELETE CASCADE, FOREIGN KEY (`token_id`) REFERENCES `account_tokens`(`id`) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS `runtime_execution_target_state` (`id` INT AUTO_INCREMENT NOT NULL PRIMARY KEY, `execution_target_id` INT NOT NULL, `success_count` INT NOT NULL DEFAULT 0, `fail_count` INT NOT NULL DEFAULT 0, `total_latency_ms` INT NOT NULL DEFAULT 0, `latency_sample_count` INT NOT NULL DEFAULT 0, `last_used_at` VARCHAR(191), `last_selected_at` VARCHAR(191), `last_fail_at` VARCHAR(191), `consecutive_fail_count` INT NOT NULL DEFAULT 0, `cooldown_level` INT NOT NULL DEFAULT 0, `cooldown_until` VARCHAR(191), `updated_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), FOREIGN KEY (`execution_target_id`) REFERENCES `runtime_execution_targets`(`id`) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS `settings` (`key` VARCHAR(191) NOT NULL PRIMARY KEY, `value` TEXT);
CREATE TABLE IF NOT EXISTS `site_announcements` (`id` INT AUTO_INCREMENT NOT NULL PRIMARY KEY, `site_id` INT NOT NULL, `platform` TEXT NOT NULL, `source_key` TEXT NOT NULL, `title` TEXT NOT NULL, `content` TEXT NOT NULL, `level` VARCHAR(191) NOT NULL DEFAULT 'info', `source_url` TEXT, `starts_at` VARCHAR(191), `ends_at` VARCHAR(191), `upstream_created_at` VARCHAR(191), `upstream_updated_at` VARCHAR(191), `first_seen_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `last_seen_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `read_at` VARCHAR(191), `dismissed_at` VARCHAR(191), `raw_payload` TEXT, FOREIGN KEY (`site_id`) REFERENCES `sites`(`id`) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS `site_api_endpoints` (`id` INT AUTO_INCREMENT NOT NULL PRIMARY KEY, `site_id` INT NOT NULL, `url` TEXT NOT NULL, `enabled` BOOLEAN DEFAULT true, `sort_order` INT DEFAULT 0, `cooldown_until` VARCHAR(191), `last_selected_at` VARCHAR(191), `last_failed_at` VARCHAR(191), `last_failure_reason` TEXT, `created_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `updated_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `base_path_mode` VARCHAR(191) NOT NULL DEFAULT 'protocol_default', FOREIGN KEY (`site_id`) REFERENCES `sites`(`id`) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS `site_day_usage` (`id` INT AUTO_INCREMENT NOT NULL PRIMARY KEY, `local_day` TEXT NOT NULL, `site_id` INT NOT NULL, `total_calls` INT NOT NULL DEFAULT 0, `success_calls` INT NOT NULL DEFAULT 0, `failed_calls` INT NOT NULL DEFAULT 0, `total_tokens` INT NOT NULL DEFAULT 0, `total_latency_ms` INT NOT NULL DEFAULT 0, `latency_count` INT NOT NULL DEFAULT 0, `created_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `updated_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), FOREIGN KEY (`site_id`) REFERENCES `sites`(`id`) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS `site_disabled_models` (`id` INT AUTO_INCREMENT NOT NULL PRIMARY KEY, `site_id` INT NOT NULL, `model_name` TEXT NOT NULL, `created_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), FOREIGN KEY (`site_id`) REFERENCES `sites`(`id`) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS `site_hour_usage` (`id` INT AUTO_INCREMENT NOT NULL PRIMARY KEY, `bucket_start_utc` TEXT NOT NULL, `site_id` INT NOT NULL, `total_calls` INT NOT NULL DEFAULT 0, `success_calls` INT NOT NULL DEFAULT 0, `failed_calls` INT NOT NULL DEFAULT 0, `total_tokens` INT NOT NULL DEFAULT 0, `total_latency_ms` INT NOT NULL DEFAULT 0, `latency_count` INT NOT NULL DEFAULT 0, `created_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `updated_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), FOREIGN KEY (`site_id`) REFERENCES `sites`(`id`) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS `token_model_availability` (`id` INT AUTO_INCREMENT NOT NULL PRIMARY KEY, `token_id` INT NOT NULL, `model_name` TEXT NOT NULL, `available` BOOLEAN, `latency_ms` INT, `checked_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), FOREIGN KEY (`token_id`) REFERENCES `account_tokens`(`id`) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS `upstream_model_cost_pricings` (`id` INT AUTO_INCREMENT NOT NULL PRIMARY KEY, `scope` TEXT NOT NULL, `scope_key` TEXT NOT NULL, `site_id` INT NOT NULL, `account_id` INT, `token_id` INT, `token_group` TEXT, `model_name` TEXT NOT NULL, `normalized_model_name` TEXT NOT NULL, `display_name` TEXT, `enabled` BOOLEAN NOT NULL DEFAULT true, `plan_json` JSON NOT NULL, `plan_fingerprint` TEXT NOT NULL, `source_type` VARCHAR(191) NOT NULL DEFAULT 'user', `metadata_json` JSON, `notes` TEXT, `created_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `updated_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), FOREIGN KEY (`account_id`) REFERENCES `accounts`(`id`) ON DELETE CASCADE, FOREIGN KEY (`site_id`) REFERENCES `sites`(`id`) ON DELETE CASCADE, FOREIGN KEY (`token_id`) REFERENCES `account_tokens`(`id`) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS `wallet_acquisition_profiles` (`id` INT AUTO_INCREMENT NOT NULL PRIMARY KEY, `scope` TEXT NOT NULL, `scope_key` TEXT NOT NULL, `site_id` INT NOT NULL, `account_id` INT, `token_id` INT, `inheritance` VARCHAR(191) NOT NULL DEFAULT 'inherit', `wallet_unit` VARCHAR(191) NOT NULL DEFAULT 'USD', `face_value_price` DOUBLE, `recharge_discount` DOUBLE NOT NULL DEFAULT 1, `daily_earned_balance` DOUBLE, `daily_earned_balance_source` VARCHAR(191) NOT NULL DEFAULT 'observed_checkin', `observed_window_days` INT, `confidence` VARCHAR(191) NOT NULL DEFAULT 'incomplete', `enabled` BOOLEAN NOT NULL DEFAULT true, `notes` TEXT, `created_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), `updated_at` VARCHAR(191) DEFAULT (DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')), FOREIGN KEY (`account_id`) REFERENCES `accounts`(`id`) ON DELETE CASCADE, FOREIGN KEY (`site_id`) REFERENCES `sites`(`id`) ON DELETE CASCADE, FOREIGN KEY (`token_id`) REFERENCES `account_tokens`(`id`) ON DELETE CASCADE);
